import { Component } from '@angular/core';
import { CompareComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [CompareComponent],
  template: `
    <cds-compare
        [summary]="'Alle Funktionen vergleichen'"
        [caption]="'Funktionsvergleich der Pakete AI.Box Core und AI.Box Pro'"
        [rowsLabel]="'Funktion'"
        [open]="false"
        [columns]="[{label: 'Core'}, {label: 'Pro', pro: true}]"
        [rows]="[{label: 'Hosting in Deutschland', cells: [true, true]}, {label: 'SSO, Nutzer- und Rechtemanagement', cells: [true, true]}, {label: 'Lokale Modelle', cells: ['bis 24 Mrd. Param.', 'bis 70 Mrd. Param.']}, {label: 'OpenAI-Modelle über API-Key', cells: [true, true]}, {label: 'Chatbots mit Modellvergleich', cells: [true, true]}, {label: 'Websuche', cells: [true, true]}, {label: 'LLM-Gateway für externe Cloud-Modelle', cells: [false, true]}, {label: 'Eigene KI-Assistenten', cells: [false, true]}, {label: 'Memory: Wissen über Chats hinweg', cells: [false, true]}, {label: 'Anbindung an Confluence und SharePoint', cells: [false, true]}, {label: 'Support pro Monat', cells: ['30 Min.', '2,5 Std.']}]"
        (toggled)="toggled($event)"
    />`,
})
export class DemoComponent {
  toggled(event: unknown) {}
}

